        local reward_sawmill_coupon_before_result, reward_sawmill_coupon_before = t.inv.count("sawmill_coupon")
        local reward_boat_repair_kit_before_result, reward_boat_repair_kit_before = t.inv.count("boat_repair_kit")
        local reward_sailing_charting_spyglass_before_result, reward_sailing_charting_spyglass_before = t.inv.count("sailing_charting_spyglass")

        -- Talk to 'Squawking' Steve Beanie to finish the quest.
        t.exec("finishQuest", t.player.talk_to, "steve_beanie", 1) -- CHECK op 1 guessed from 'talk'
        -- CHECK branch (page 1): single guard '%varb18314_sailing_intro >= ^pan_complete' unresolved -- assumed false, not entered
        -- CHECK branch (page 1): single guard '%varb18314_sailing_intro = ^pan_grog | %varb18314_sailing_intro = ^pan_finish' unresolved -- assumed false, not entered
        -- CHECK branch (page 1): single guard '%varb18314_sailing_intro >= ^pan_jim & %varb18314_sailing_intro < ^pan_grog' unresolved -- assumed false, not entered
        -- CHECK branch (page 1): single guard '%varb18314_sailing_intro >= ^pan_ribs & %varb18314_sailing_intro < ^pan_ship' unresolved -- assumed false, not entered
        t.exec("finishQuest-dialog", t.chat.play, {
            "npc:Squawk!",
        })


        t.quest.expect_complete()

        -- Reward checks -- the quest's actual reward, not just its completion (H2, docs/QUEST_SUITE_KIT.md).
        t.check("reward.sailing", t.skill.expect_gain("sailing", 300, reward_before))
        local reward_sawmill_coupon_after_result, reward_sawmill_coupon_after = t.inv.count("sawmill_coupon")
        t.check("reward.sawmill_coupon", reward_sawmill_coupon_before_result == "ok" and reward_sawmill_coupon_after_result == "ok" and reward_sawmill_coupon_after == reward_sawmill_coupon_before + 25, string.format("sawmill_coupon %s -> %s (want +25), reads %s/%s", tostring(reward_sawmill_coupon_before), tostring(reward_sawmill_coupon_after), tostring(reward_sawmill_coupon_before_result), tostring(reward_sawmill_coupon_after_result)))
        local reward_boat_repair_kit_after_result, reward_boat_repair_kit_after = t.inv.count("boat_repair_kit")
        t.check("reward.boat_repair_kit", reward_boat_repair_kit_before_result == "ok" and reward_boat_repair_kit_after_result == "ok" and reward_boat_repair_kit_after == reward_boat_repair_kit_before + 2, string.format("boat_repair_kit %s -> %s (want +2), reads %s/%s", tostring(reward_boat_repair_kit_before), tostring(reward_boat_repair_kit_after), tostring(reward_boat_repair_kit_before_result), tostring(reward_boat_repair_kit_after_result)))
        local reward_sailing_charting_spyglass_after_result, reward_sailing_charting_spyglass_after = t.inv.count("sailing_charting_spyglass")
        t.check("reward.sailing_charting_spyglass", reward_sailing_charting_spyglass_before_result == "ok" and reward_sailing_charting_spyglass_after_result == "ok" and reward_sailing_charting_spyglass_after == reward_sailing_charting_spyglass_before + 1, string.format("sailing_charting_spyglass %s -> %s (want +1), reads %s/%s", tostring(reward_sailing_charting_spyglass_before), tostring(reward_sailing_charting_spyglass_after), tostring(reward_sailing_charting_spyglass_before_result), tostring(reward_sailing_charting_spyglass_after_result)))

        t.finish(0)
    end,
}
